    if let Some(output) = PREMINE_OUTPUTS.iter().find(|o| o.address == address) {
        if let Some(unlock) = output.unlock_height {
            if current_height < unlock {
                return Err(format!(
                    "premine address {} locked until block {} (current: {})",
                    address, unlock, current_height
                ));
            }
        }
    }
    Ok(())
