                    cfg = file_cfg;
                }
                Err(e) => {
                    tracing::warn!("Could not load DAO_CONFIG={}: {} — using defaults", path, e);
                }
            }
        }

        // Level 3: env var overrides (can patch individual keys without editing TOML)
        if let Ok(v) = env::var("DAO_API_PORT") {
            if let Ok(p) = v.parse::<u16>() {
                cfg.api_port = p;
